import unittest
from graph import topological_layers
class T(unittest.TestCase):
    def test_layers_include_dependency_only_nodes(self):
        self.assertEqual(topological_layers({'build':['fetch'], 'test':['build'], 'fetch':[], 'ship':['test']}), [['fetch'], ['build'], ['test'], ['ship']])
    def test_stable_parallel_layer(self):
        self.assertEqual(topological_layers({'b':[], 'a':[], 'c':['a','b']}), [['a','b'], ['c']])
    def test_cycle(self):
        with self.assertRaises(ValueError): topological_layers({'a':['b'], 'b':['a']})
